INSERT INTO services(title,slug,excerpt,body,image_url,icon,sort_order) VALUES
('Inventory Control','inventory-control','Track stock levels, product movement and availability in real time.','Manage products, stock levels, minimum stock thresholds, categories and daily inventory operations.','https://images.unsplash.com/photo-1553413077-190dd305871c?auto=format&fit=crop&w=1200&q=80','fa-solid fa-boxes-stacked',1),
('Stock In & Out','stock-movements','Record every receipt, sale, transfer, loss or adjustment.','Every movement records quantity before and after, user, reason and reference for a useful audit trail.','https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80','fa-solid fa-arrow-right-arrow-left',2),
('Reports & Analytics','reports-analytics','Turn inventory records into practical business reports.','Use stock value, movement trends, category performance and low-stock reports to support purchasing decisions.','https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80','fa-solid fa-chart-line',3),
('Supplier Management','supplier-management','Keep supplier contacts and sourcing details organised.','Store supplier contact data and map suppliers to products without rigid database relationship constraints.','https://images.unsplash.com/photo-1521791055366-0d553872125f?auto=format&fit=crop&w=1200&q=80','fa-solid fa-truck-fast',4),
('Content Management','content-management','Manage blogs, events, testimonials and featured products.','Publish public-facing content through the same secure back office used for inventory.','https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=1200&q=80','fa-solid fa-pen-to-square',5),
('Customer Enquiries','customer-enquiries','Capture website leads and newsletter subscribers in one place.','AJAX forms save enquiries and subscriptions immediately and attempt confirmation email delivery.','https://images.unsplash.com/photo-1525182008055-f88b95ff7980?auto=format&fit=crop&w=1200&q=80','fa-solid fa-headset',6);
INSERT INTO blogs(title,slug,excerpt,body,image_url,status,published_at) VALUES
('5 Signs Your Business Has Outgrown Spreadsheets','outgrown-spreadsheets','When stock records start becoming difficult to trust, the problem is often the process rather than the people.','Growing businesses need consistent stock movement records, minimum stock thresholds, role-based workflows and reports that can be reviewed without manually rebuilding spreadsheets.','https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?auto=format&fit=crop&w=1200&q=80','published',NOW()),
('How Low-Stock Alerts Protect Daily Sales','low-stock-alerts','A reorder level gives your team time to act before the shelf is empty.','Low-stock alerts are most useful when every product has a minimum stock level based on lead time, sales speed and the cost of holding inventory.','https://images.unsplash.com/photo-1601598851547-4302969d0614?auto=format&fit=crop&w=1200&q=80','published',DATE_SUB(NOW(),INTERVAL 4 DAY)),
('Stock In, Stock Out and the Audit Trail','stock-audit-trail','Quantity alone does not explain how inventory changed.','Professional stock systems keep a movement history with the product, quantity, movement type, reason, reference, user and before/after stock values.','https://images.unsplash.com/photo-1586864387789-628af9feed72?auto=format&fit=crop&w=1200&q=80','published',DATE_SUB(NOW(),INTERVAL 9 DAY)),
('Better Product Data Means Better Reports','better-product-data','Consistent categories, units and SKUs make inventory reporting more useful.','Clean product master data reduces duplication and improves category summaries, stock valuation and supplier analysis.','https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1200&q=80','published',DATE_SUB(NOW(),INTERVAL 14 DAY));
INSERT INTO events(title,slug,excerpt,body,image_url,event_date,location,status) VALUES
('Inventory Accuracy Workshop','inventory-accuracy-workshop','A practical session on stock counts, movement records and reorder levels.','This session demonstrates product setup, stock in/out, stock counts, low-stock monitoring and management reporting.','https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&w=1200&q=80',DATE_ADD(CURDATE(),INTERVAL 14 DAY),'Lusaka','published'),
('Small Business Digital Operations Clinic','digital-operations-clinic','Learn how simple digital systems improve daily operations.','A hands-on clinic covering inventory, customer enquiries, reporting, website content and practical digital workflows.','https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=80',DATE_ADD(CURDATE(),INTERVAL 30 DAY),'Online / Lusaka','published'),
('StockFlow Product Demo','stockflow-product-demo','See the full inventory and content dashboard in action.','An overview of the public website, product catalogue, stock movements, dashboards, newsletter and content management.','https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1200&q=80',DATE_ADD(CURDATE(),INTERVAL 45 DAY),'Online','published');
INSERT INTO testimonials(name,role,quote,status) VALUES('Tawanda M.','Retail Manager','The dashboard makes it much easier to see which products need attention before we run out.','published'),('Ruth K.','Operations Lead','The stock movement history gives us a clearer audit trail than our old spreadsheet process.','published'),('Daniel P.','Business Owner','The interface is clean enough for daily use while still giving us useful reports and content tools.','published');
