INSERT INTO gallery(title,caption,image_url,category,sort_order) VALUES ('Warehouse Control','Accurate receiving and stock movement workflows.','https://images.unsplash.com/photo-1553413077-190dd305871c?auto=format&fit=crop&w=1200&q=80','Inventory',1),('Product Organisation','Clear categories and product visibility.','https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80','Products',2),('Business Analytics','Use stock data to support better decisions.','https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80','Reports',3);
