DROP DATABASE IF EXISTS inventory_manager_v2;
CREATE DATABASE inventory_manager_v2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE inventory_manager_v2;

CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'editor',status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_user_email(email));

CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_category_slug(slug));
CREATE TABLE products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,sku VARCHAR(80) NOT NULL,category_id INT UNSIGNED DEFAULT NULL,unit VARCHAR(40) NOT NULL,buying_price DECIMAL(12,2) NOT NULL DEFAULT 0,selling_price DECIMAL(12,2) NOT NULL DEFAULT 0,quantity INT NOT NULL DEFAULT 0,minimum_stock INT NOT NULL DEFAULT 5,description TEXT,image_url VARCHAR(500),featured TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_product_sku(sku),INDEX idx_product_category(category_id),INDEX idx_product_status(status),INDEX idx_product_stock(quantity,minimum_stock));
CREATE TABLE stock_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,type VARCHAR(10) NOT NULL,quantity INT NOT NULL,stock_before INT NOT NULL,stock_after INT NOT NULL,reason VARCHAR(180),reference_no VARCHAR(100),user_id INT UNSIGNED DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_tx_product(product_id),INDEX idx_tx_date(created_at),INDEX idx_tx_type(type));
CREATE TABLE suppliers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,contact_person VARCHAR(120),phone VARCHAR(50),email VARCHAR(190),address VARCHAR(255),status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_supplier_name(name));
CREATE TABLE product_suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,supplier_id INT UNSIGNED NOT NULL,supplier_sku VARCHAR(100),last_cost DECIMAL(12,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_ps_product(product_id),INDEX idx_ps_supplier(supplier_id));
CREATE TABLE blogs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(220) NOT NULL,category VARCHAR(120),favicon VARCHAR(500),keywords VARCHAR(500),excerpt TEXT,body LONGTEXT,image_url VARCHAR(500),seo_title VARCHAR(220),meta_description VARCHAR(320),og_title VARCHAR(220),og_description VARCHAR(320),og_image VARCHAR(500),status VARCHAR(30) DEFAULT 'draft',published_at DATETIME DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_blog_slug(slug),INDEX idx_blog_status(status),INDEX idx_blog_published(published_at));
CREATE TABLE blog_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,blog_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,comment TEXT NOT NULL,status VARCHAR(30) DEFAULT 'approved',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_comment_blog(blog_id),INDEX idx_comment_status(status));
CREATE TABLE blog_reactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,blog_id INT UNSIGNED NOT NULL,visitor_token VARCHAR(100) NOT NULL,reaction VARCHAR(10) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_reaction_blog(blog_id),INDEX idx_reaction_token(visitor_token));
CREATE TABLE events(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(220) NOT NULL,category VARCHAR(120),favicon VARCHAR(500),keywords VARCHAR(500),excerpt TEXT,body LONGTEXT,image_url VARCHAR(500),seo_title VARCHAR(220),meta_description VARCHAR(320),og_title VARCHAR(220),og_description VARCHAR(320),og_image VARCHAR(500),event_date DATE NOT NULL,location VARCHAR(200),status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_event_slug(slug),INDEX idx_event_date(event_date));
CREATE TABLE testimonials(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,role VARCHAR(160),quote TEXT NOT NULL,image_url VARCHAR(500),status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_testimonial_status(status));
CREATE TABLE services(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(180) NOT NULL,excerpt TEXT,body LONGTEXT,image_url VARCHAR(500),icon VARCHAR(120) DEFAULT 'fa-solid fa-boxes-stacked',sort_order INT DEFAULT 0,status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_service_slug(slug),INDEX idx_service_sort(sort_order));
CREATE TABLE contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60),service VARCHAR(120),message TEXT NOT NULL,status VARCHAR(30) DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_contact_status(status),INDEX idx_contact_date(created_at));
CREATE TABLE newsletter_subscribers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_news_email(email),INDEX idx_news_status(status));
CREATE TABLE gallery(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,caption TEXT,image_url VARCHAR(500) NOT NULL,category VARCHAR(100),sort_order INT DEFAULT 0,status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_gallery_status(status),INDEX idx_gallery_sort(sort_order));
CREATE TABLE site_settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_name VARCHAR(150),email VARCHAR(190),phone VARCHAR(60),address VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE VIEW v_stock_history AS SELECT t.id,t.created_at,t.type,t.quantity,t.stock_before,t.stock_after,t.reason,t.reference_no,p.name AS product_name,p.sku,u.name AS user_name FROM stock_transactions t LEFT JOIN products p ON p.id=t.product_id LEFT JOIN users u ON u.id=t.user_id;
CREATE VIEW v_low_stock AS SELECT p.id,p.name,p.sku,p.quantity,p.minimum_stock,p.unit,c.name AS category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='active' AND p.quantity<=p.minimum_stock;
CREATE VIEW v_dashboard_stats AS SELECT (SELECT COUNT(*) FROM products WHERE status='active') total_products,(SELECT COALESCE(SUM(quantity),0) FROM products WHERE status='active') stock_units,(SELECT COALESCE(SUM(quantity*buying_price),0) FROM products WHERE status='active') stock_value,(SELECT COALESCE(SUM(quantity*selling_price),0) FROM products WHERE status='active') retail_value,(SELECT COUNT(*) FROM products WHERE status='active' AND quantity<=minimum_stock) low_stock,(SELECT COUNT(*) FROM products WHERE status='active' AND quantity<=0) out_of_stock,(SELECT COUNT(*) FROM newsletter_subscribers WHERE status='active') subscribers,(SELECT COUNT(*) FROM contacts) enquiries,(SELECT COUNT(*) FROM blogs WHERE status='published') published_blogs,(SELECT COUNT(*) FROM events WHERE status='published' AND event_date>=CURDATE()) upcoming_events;


